const NIH = name => `https://ods.od.nih.gov/factsheets/${name}-Consumer/`;
const VC = name => `https://www.voedingscentrum.nl/encyclopedie/${name}.aspx`;
const COFID = 'https://www.gov.uk/government/publications/composition-of-foods-integrated-dataset-cofid';

const nutrient = (id, name, unit, target, group, kind, about, low, foods, source, high = '') => ({
  id, name, unit, target, group, kind, about, low, foods, source, high,
  targetSource: ['fiber', 'water'].includes(id) ? source : EU,
  targetNote: ['fiber', 'water'].includes(id) ? 'Aanpasbaar voorbeeld voor volwassenen; geen persoonlijk advies.' : 'EU-etiketreferentie voor volwassenen; geen persoonlijke behoefte of diagnosegrens.'
});

